/* generated by tools/screens/gen.py from workbench/ui/screens.json, workbench/rows.json,
   workbench/options.json and workbench/ui/vocab.json. Never edit this file. */
#ifndef UI_CHOICES_GEN_H
#define UI_CHOICES_GEN_H
#include <stdint.h>

/* The rows, in workbench/rows.json's order, then the screens' own (rhythm: the Comp part's one Rhythm row, comp
   or strumPat as ch_rhythm_row says; loop: the Loop section switch). A row's value is the workbench's (a kick
   phrase's: 0 the pattern's own, 1.. options.json's kickPhrases in order). Rows with no
   table here (seed, map, prog, family, the re-rolls, and any row no screen names): ch_count 0, ch_name
   NULL; the engine's library or a number names them. */
enum {
    ROW_SEED,
    ROW_KEY,
    ROW_MODE,
    ROW_TEMPO,
    ROW_SWING,
    ROW_MOOD,
    ROW_MOTION,
    ROW_MAP,
    ROW_PROG,
    ROW_COLOR,
    ROW_FAMILY,
    ROW_KEYS,
    ROW_COMP,
    ROW_LEAD,
    ROW_BASS,
    ROW_PAD,
    ROW_PAD_ON,
    ROW_PHRASE,
    ROW_LEAD_STYLE,
    ROW_LEAD_LOOP,
    ROW_LEAD_OCT,
    ROW_BUSY_THIN,
    ROW_KEYS_WITH,
    ROW_VOICINGS,
    ROW_KEYS_OCT,
    ROW_STRUM_PAT,
    ROW_STRUM_FILL,
    ROW_PAD_PLACE,
    ROW_BASS_LINE,
    ROW_PAD_NOTES,
    ROW_DRUMS_VAR,
    ROW_KIT,
    ROW_PATTERN,
    ROW_KICK,
    ROW_RIDE,
    ROW_DUST,
    ROW_NOISE,
    ROW_AMBIENCE,
    ROW_RHYTHM,
    ROW_LOOP,
    ROW_ENDLESS,
    ROW_N
};

/* a choice's flags (ch_flags): its status in the low 2 bits (0 approved, 1 candidate, 2 retired: behind
   "show retired", 3 removed: never offered), CH_HIDDEN never offered itself (shown as the current value
   only), CH_ROLLED the engine's own choice ("as rolled"), CH_FAM an instrument's or kit's family (0 none,
   CH_ACOUSTIC, CH_SYNTH, CH_ELECTRIC, CH_ANY: options.json's) */
#define CH_STATUS(f) ((f) & 3)
#define CH_HIDDEN 4
#define CH_ROLLED 8
#define CH_FAM(f) ((f) >> 4 & 7)
enum { CH_ACOUSTIC = 1, CH_SYNTH, CH_ELECTRIC, CH_ANY };

const char *ch_name(int row, int value);          /* its name as the device writes it; NULL: no such choice */
int ch_count(int row);                            /* its choices, in the workbench's order */
int ch_value(int row, int index);
int ch_flags(int row, int value);                 /* -1: no such choice */
int ch_is_retired(int row, int value);            /* retired or removed */
/* a choice fits the comp instrument keys_ins: a comping style (ROW_COMP) iff (!keys || keys contains it) and
   !(notKeys contains it) (rows.json's fits.comping); every other row's always */
int ch_fits(int row, int value, int keys_ins);
/* rows.js's rhythmRow: ROW_STRUM_PAT when the strum style fits keys_ins and comp (a ROW_COMP value) is as
   rolled, strum or a style that fits; else ROW_COMP */
int ch_rhythm_row(int keys_ins, int comp);
/* each row's request on the song (song.h's song_request_row: SR_ROLL + RF_*, SR_ROLE + V_*, SR_OV + OV_*,
   SR_KIT), -1 where it takes none. The comp row's value is the workbench's: a comp rhythm (from 100) is the
   COMP_PAT override, anything else COMP */
extern const int8_t CH_SONG_ROW[ROW_N];
extern const char *const CH_ROW_ID[ROW_N];      /* each row's id (rows.json's: the live state) */

#endif
